
.entry-shell {
  min-height: 100vh;
  padding: 1.2rem;
  background:
    radial-gradient(circle at top left, rgba(191, 150, 76, 0.14), transparent 24%),
    radial-gradient(circle at top right, rgba(81, 108, 61, 0.14), transparent 25%),
    linear-gradient(180deg, #140d09 0%, #070606 100%);
  color: #fff2d7;
}

.entry-card {
  width: min(76rem, 100%);
  margin: 0 auto;
  display: grid;
  gap: 1rem;
}

.entry-note {
  display: grid;
  gap: 0.65rem;
  padding: 1rem 1.1rem;
  border: 1px solid rgba(214, 196, 150, 0.18);
  border-radius: 1.55rem;
  background:
    radial-gradient(circle at top left, rgba(229, 198, 128, 0.1), transparent 30%),
    linear-gradient(180deg, rgba(36, 25, 18, 0.94), rgba(15, 10, 8, 0.96));
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.28);
}

.entry-note span {
  display: inline-block;
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  color: rgba(227, 196, 122, 0.9);
  text-transform: uppercase;
}

.entry-note h1 {
  margin: 0.35rem 0 0;
  font-size: clamp(1.3rem, 4vw, 2.2rem);
  color: #f4e3b6;
  line-height: 1.1;
}

.entry-note p {
  margin: 0;
  line-height: 1.7;
  color: rgba(244, 236, 213, 0.82);
}

@media (max-width: 900px) {
  .entry-shell {
    padding: 0.8rem;
  }
}
